"use client";

import { useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { MoreHorizontal } from "lucide-react";
import type { BillingControlsPresentation } from "@/components/billing-controls";
import { SUPPORT_EMAIL } from "@/lib/pricing";

const focusRing =
  "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--appearance-focus,var(--ring))]";
const menuItem = `block w-full rounded-[var(--appearance-radius,10px)] px-3.5 py-2.5 text-left text-sm font-medium text-[var(--foreground)] css-hover:bg-[var(--appearance-wash,var(--surface))] disabled:cursor-not-allowed disabled:opacity-55 ${focusRing}`;

export function SubscriptionMenu({
  controls: c,
}: {
  controls: BillingControlsPresentation;
}) {
  const id = useId();
  const trigger = useRef<HTMLButtonElement>(null);
  const menu = useRef<HTMLDivElement>(null);
  const initialFocus = useRef<"first" | "last">("first");
  const [open, setOpen] = useState(false);

  function close() {
    setOpen(false);
    trigger.current?.focus();
  }

  useLayoutEffect(() => {
    if (!open) return;
    function reposition() {
      if (!trigger.current || !menu.current) return;
      const anchor = trigger.current.getBoundingClientRect();
      const bounds = menu.current.getBoundingClientRect();
      const above =
        window.innerHeight - anchor.bottom - 8 < bounds.height &&
        anchor.top > window.innerHeight - anchor.bottom;
      const left = Math.max(
        10,
        Math.min(
          anchor.right - bounds.width,
          window.innerWidth - bounds.width - 10,
        ),
      );
      const top = Math.max(
        10,
        Math.min(
          above ? anchor.top - bounds.height - 8 : anchor.bottom + 8,
          window.innerHeight - bounds.height - 10,
        ),
      );
      Object.assign(menu.current.style, {
        left: `${left}px`,
        top: `${top}px`,
        visibility: "visible",
      });
    }
    reposition();
    const items = menu.current?.querySelectorAll<HTMLElement>(
      '[role="menuitem"]:not(:disabled)',
    );
    items?.[initialFocus.current === "last" ? items.length - 1 : 0]?.focus();
    const observer = new ResizeObserver(reposition);
    if (menu.current) observer.observe(menu.current);
    window.addEventListener("resize", reposition);
    window.addEventListener("scroll", reposition, true);
    return () => {
      observer.disconnect();
      window.removeEventListener("resize", reposition);
      window.removeEventListener("scroll", reposition, true);
    };
  }, [open]);

  useEffect(() => {
    if (!open) return;
    function outside(event: MouseEvent) {
      if (
        event.target instanceof Node &&
        !menu.current?.contains(event.target) &&
        !trigger.current?.contains(event.target)
      )
        close();
    }
    function escape(event: KeyboardEvent) {
      if (event.key === "Escape") {
        event.preventDefault();
        close();
      }
    }
    document.addEventListener("click", outside);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("click", outside);
      document.removeEventListener("keydown", escape);
    };
  }, [open]);

  return (
    <>
      <button
        ref={trigger}
        type="button"
        aria-label="More subscription actions"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? id : undefined}
        className={`css-hover:bg-[var(--settings-inset)] css-hover:border-[var(--settings-strong)] aria-expanded:bg-[var(--settings-inset)] grid size-11 flex-none place-items-center rounded-full border border-[var(--settings-strong)] text-[var(--settings-text)] cursor-pointer ${focusRing}`}
        onClick={() => {
          if (open) close();
          else {
            initialFocus.current = "first";
            setOpen(true);
          }
        }}
        onKeyDown=[REDACTED_SECRET]
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            initialFocus.current = event.key === "ArrowUp" ? "last" : "first";
            setOpen(true);
          }
        }}
      >
        <MoreHorizontal className="size-5" aria-hidden="true" />
      </button>
      {open &&
        createPortal(
          <div
            ref={menu}
            id={id}
            role="menu"
            aria-label="Subscription actions"
            className="fixed z-[1000] min-w-[230px] max-w-[calc(100vw-20px)] overflow-y-auto rounded-[var(--appearance-radius,16px)] border border-[var(--appearance-border,var(--border))] bg-[var(--appearance-card,var(--card))] p-1.5 font-[family-name:var(--font-plus-jakarta)] text-[var(--foreground)] shadow-[0_16px_44px_var(--color-plancard-shadow-1)]"
            style={{
              left: 10,
              top: 10,
              maxHeight: "calc(100dvh - 20px)",
              visibility: "hidden",
            }}
            onClick={(event) => {
              if (
                (event.target as HTMLElement).closest(
                  '[role="menuitem"]:not(:disabled)',
                )
              )
                close();
            }}
            onKeyDown=[REDACTED_SECRET]
              if (event.key === "Tab") {
                event.preventDefault();
                close();
                return;
              }
              if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key))
                return;
              event.preventDefault();
              const items = Array.from(
                event.currentTarget.querySelectorAll<HTMLElement>(
                  '[role="menuitem"]:not(:disabled)',
                ),
              );
              const current = items.indexOf(
                document.activeElement as HTMLElement,
              );
              const next =
                event.key === "Home"
                  ? 0
                  : event.key === "End"
                    ? items.length - 1
                    : (current +
                        (event.key === "ArrowDown" ? 1 : -1) +
                        items.length) %
                      items.length;
              items[next]?.focus();
            }}
          >
            <button
              type="button"
              role="menuitem"
              tabIndex={-1}
              className={menuItem}
              onClick={() => void c.refresh()}
            >
              Refresh subscription status
            </button>
            {c.canCancel && (
              <button
                type="button"
                role="menuitem"
                tabIndex={-1}
                className={menuItem}
                disabled={c.busy || c.billing?.cancellationPending}
                onClick={() => void c.open("cancel")}
              >
                {c.billing?.cancellationPending
                  ? "Cancellation pending"
                  : "Cancel at period end"}
              </button>
            )}
            <a
              role="menuitem"
              tabIndex={-1}
              className={menuItem}
              href={`mailto:${SUPPORT_EMAIL}`}
            >
              Contact support
            </a>
          </div>,
          document.getElementById("main-content") ?? document.body,
        )}
    </>
  );
}
